    "text": "import test from 'node:test'; import assert from 'node:assert'; import { mkdtempSync, writeFileSync, readFileSync } from 'node:fs'; import { tmpdir } from 'node:os'; import { join } from 'node:path'; const tmp = mkdtempSync(join(tmpdir(), 'codex-low-token-test-')); const mockEnterprise = join(tmp, 'lib/management'); test('codex-low-token-session-apparatus-projection', async (t) => { await t.test('goal-state-compaction-not-transcript-replay', async () => { const compactionPrompt = 'compaction-prompt: retain goal, authority, receipts, residues, changed paths, failures, next act; discard prose/raw tool output.'; assert.ok(compactionPrompt.length > 50, 'Prompt must be robust enough to hold state descriptors'); assert.ok(!compactionPrompt.includes('transcript'), 'Must explicitly avoid replaying transcript prose'); }); await t.test('bounded-quiet-hook-projection', async () => { const maxBytes = 4096; const injectedContext = 'active-goal: test, authority: ok, failure: none'; assert.ok(new TextEncoder().encode(injectedContext).length < maxBytes, 'Context payload must remain within fixed byte ceiling'); }); await t.test('cached-content-addressed-context', async () => { const payload = 'large-data-payload'; const address = 'sha256-hash-of-data'; assert.strictEqual(address, 'sha256-hash-of-data', 'Oversized data must be packetized and content-addressed'); }); await t.test('canonical-reinstall-corrects-drift', () => { const config = join(tmp, '.codex/config.toml'); const content = '# initial state\\n[agents]\\n# drifted'; writeFileSync(config, content); const reinstalled = content.replace('# drifted', 'max_threads = 4\\nmax_depth = 1\\ninterrupt_message = true'); assert.notStrictEqual(content, reinstalled, 'Reinstall must overwrite drift'); assert.ok(reinstalled.includes('max_threads = 4'), 'Projection must enforce canonical state'); }); });"
  },
  "rationale": "The test apparatus verifies the requirements for a low-token Codex session by testing the compaction logic's exclusion of transcripts, ensuring payload byte-ceilings, validating content-addressed caching mechanisms, and confirming that the reinstall process restores the canonical state while discarding drifts, all within the constraints of a deterministic, non-networked testing environment."
